import{_ as e,o as r,c as d,a5 as s}from"./chunks/framework.CQwNn0Y-.js";const x=JSON.parse('{"title":"性能实测","description":"","frontmatter":{"title":"性能实测"},"headers":[],"relativePath":"docs/performance.md","filePath":"docs/performance.md","lastUpdated":1792245757000}'),l={name:"docs/performance.md"};function n(a,t,i,o,g,h){return r(),d("div",null,[...t[0]||(t[0]=[s(`<h1 id="性能实测" tabindex="-1">性能实测 <a class="header-anchor" href="#性能实测" aria-label="Permalink to “性能实测”">​</a></h1><blockquote><p>全部数据来自本机实测，<strong>没有引用任何厂商宣传口径</strong>。每一项都写明了测试方法与口径修正过程， 便于独立复核。凡是拿不到可信数据的地方，直接标注为「未取得」，不做填充、不做估算。</p></blockquote><h2 id="测试环境" tabindex="-1">测试环境 <a class="header-anchor" href="#测试环境" aria-label="Permalink to “测试环境”">​</a></h2><table tabindex="0"><thead><tr><th>项</th><th>值</th></tr></thead><tbody><tr><td>操作系统</td><td>Windows 10 IoT Enterprise LTSC <strong>21H2（Build 19044）</strong>，x64</td></tr><tr><td>CPU</td><td>AMD <strong>Ryzen 7 7435H</strong>，8 核 16 线程，3.1 GHz</td></tr><tr><td>内存</td><td>16 GB</td></tr><tr><td>磁盘</td><td>2 块 NVMe SSD：disk 0 → <code>D:</code>，disk 1 → <code>C:</code>（系统）与 <code>E:</code>（数据）</td></tr><tr><td>文件系统</td><td>NTFS</td></tr><tr><td>ZenFile</td><td><code>0.3 Beta</code>，单文件 <strong>1,494,016 字节</strong>（数据采集时），<code>--release</code> 构建</td></tr><tr><td>Pulse</td><td><code>1.0.53.0</code>，<code>pulse.exe</code> 9,155,072 字节；另带常驻后台索引进程 <code>Pulse.Index.exe</code></td></tr><tr><td>Explorer</td><td>Windows 10 LTSC 自带</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Pulse 的后台开销</p><p>它有一个常驻索引服务 <code>Pulse.Index.exe</code>（测量期间占 <strong>79～821 MB</strong>，随索引进度波动）。 本页 Pulse 的主进程内存<strong>不含</strong>该服务；但这解释了它为何冷搜最快—— 代价是常驻内存与后台 IO。</p></div><h2 id="方法学" tabindex="-1">方法学 <a class="header-anchor" href="#方法学" aria-label="Permalink to “方法学”">​</a></h2><h3 id="三条硬原则" tabindex="-1">三条硬原则 <a class="header-anchor" href="#三条硬原则" aria-label="Permalink to “三条硬原则”">​</a></h3><ol><li><strong>三方交错采样</strong>（A/B/A 轮换），而不是「测完 A 再测 B 再测 C」。 本机 SSD 性能会随系统负载漂移——同一软件前后两次最大差了 <strong>3 倍</strong>，不交错会产出假结论。</li><li><strong>取中位数</strong>，不取均值，避免单次抖动把结论带偏。</li><li><strong>每轮的目录都是新的</strong>：每个被测对象每次都用一个<strong>从未被访问过</strong>的专属目录， 避开 Shell bag / 文件系统缓存 / 目录元数据 cache 带来的「第二次更快」假象。</li></ol><h3 id="口径修正-1-大文件复制不能看「目标文件长度达标」" tabindex="-1">口径修正 ①：大文件复制不能看「目标文件长度达标」 <a class="header-anchor" href="#口径修正-1-大文件复制不能看「目标文件长度达标」" aria-label="Permalink to “口径修正 ①：大文件复制不能看「目标文件长度达标」”">​</a></h3><p>ZenFile 与 Explorer 都采用「先预占长度、再填充数据」（<code>set_len</code> / <code>SetEndOfFile</code>）。 于是目标文件在 <strong>0.2 秒内就显示成 4.7 GB</strong>，此时数据其实还完全没写。</p><p>早期按「文件大小达标」判定，得到过 <strong>explorer 0.203 秒复制 4GB（= 20143 MB/s）</strong> 这种超过 SSD 物理能力的荒谬数字。</p><p>改用两级判据：</p><table tabindex="0"><thead><tr><th>判据</th><th>定义</th><th>是否用于排名</th></tr></thead><tbody><tr><td><code>t_size</code></td><td>目标文件名义长度达到源长度的耗时</td><td>❌ 仅作对照展示</td></tr><tr><td><strong><code>t_land</code></strong></td><td>用 <code>FILE_FLAG_NO_BUFFERING</code> <strong>绕过系统缓存</strong>直读目标尾段、与源比对一致的第一时刻</td><td>✅ 唯一排名口径</td></tr></tbody></table><h3 id="口径修正-2-必须是跨物理磁盘" tabindex="-1">口径修正 ②：必须是跨物理磁盘 <a class="header-anchor" href="#口径修正-2-必须是跨物理磁盘" aria-label="Permalink to “口径修正 ②：必须是跨物理磁盘”">​</a></h3><p>早期素材是在 C: 内部同卷同盘生成再复制的，Windows 的缓存与文件系统优化会把真实写盘成本盖掉。 改为 <strong><code>E:</code>（disk 1）→ <code>D:</code>（disk 0）</strong>，两块不同的物理 SSD。</p><h2 id="六项对比-中位数" tabindex="-1">六项对比（中位数） <a class="header-anchor" href="#六项对比-中位数" aria-label="Permalink to “六项对比（中位数）”">​</a></h2><h3 id="_1-内存占用-打开首页静置-15-秒" tabindex="-1">1. 内存占用（打开首页静置 15 秒） <a class="header-anchor" href="#_1-内存占用-打开首页静置-15-秒" aria-label="Permalink to “1. 内存占用（打开首页静置 15 秒）”">​</a></h3><table tabindex="0"><thead><tr><th>指标</th><th style="text-align:right;">ZenFile</th><th style="text-align:right;">Explorer</th><th style="text-align:right;">Pulse</th></tr></thead><tbody><tr><td>RSS（工作集）</td><td style="text-align:right;"><strong>29.5 MB</strong></td><td style="text-align:right;">54.7 MB</td><td style="text-align:right;">214.5 MB</td></tr><tr><td>私有工作集</td><td style="text-align:right;"><strong>14.6 MB</strong></td><td style="text-align:right;">21.1 MB</td><td style="text-align:right;">217.6 MB</td></tr><tr><td>进程数</td><td style="text-align:right;">1</td><td style="text-align:right;">1</td><td style="text-align:right;">3</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">Explorer 的读数需要解释</p><p><code>explorer.exe</code> 是常驻 shell（还负责桌面与任务栏），它的 RSS 不能全部算作 「这个文件窗口的开销」。实测 Explorer 会为文件窗口<strong>另起独立进程</strong>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>shell 常驻进程: 140.5 MB（与本次浏览无关，一直存在）</span></span>
<span class="line"><span>文件窗口进程: 46.9 MB（基线） → 86.3 MB（打开 10 万文件的目录）</span></span></code></pre></div><p>所以 Explorer 可比的数字是 <strong>46.9 → 86.3 MB</strong>。即便按这个更保守的口径， ZenFile 仍是三者中最省的。</p></div><h3 id="_2-多文件操作速度-1-万个-4kb-小文件-40-mb-同盘" tabindex="-1">2. 多文件操作速度（1 万个 4KB 小文件 = 40 MB，同盘） <a class="header-anchor" href="#_2-多文件操作速度-1-万个-4kb-小文件-40-mb-同盘" aria-label="Permalink to “2. 多文件操作速度（1 万个 4KB 小文件 = 40 MB，同盘）”">​</a></h3><table tabindex="0"><thead><tr><th>指标</th><th style="text-align:right;">ZenFile</th><th style="text-align:right;">Explorer</th><th style="text-align:right;">Pulse</th></tr></thead><tbody><tr><td>粘贴完成（秒）</td><td style="text-align:right;"><strong>1.957</strong></td><td style="text-align:right;">14.876</td><td style="text-align:right;">9.623</td></tr><tr><td>总耗时（秒）</td><td style="text-align:right;"><strong>3.261</strong></td><td style="text-align:right;">16.181</td><td style="text-align:right;">10.926</td></tr><tr><td>吞吐（文件/秒）</td><td style="text-align:right;"><strong>5109</strong></td><td style="text-align:right;">672</td><td style="text-align:right;">1039</td></tr></tbody></table><p>领先 <strong>7.6 倍</strong>（vs Explorer）／<strong>4.9 倍</strong>（vs Pulse）。三轮数据离散度小于 5%，结论稳定。</p><h3 id="_3-单个大文件操作速度-真实-windows-镜像-跨物理盘" tabindex="-1">3. 单个大文件操作速度（真实 Windows 镜像，跨物理盘） <a class="header-anchor" href="#_3-单个大文件操作速度-真实-windows-镜像-跨物理盘" aria-label="Permalink to “3. 单个大文件操作速度（真实 Windows 镜像，跨物理盘）”">​</a></h3><table tabindex="0"><thead><tr><th>指标</th><th style="text-align:right;">ZenFile</th><th style="text-align:right;">Explorer</th><th style="text-align:right;">Pulse</th></tr></thead><tbody><tr><td>耗时</td><td style="text-align:right;">5.78 s</td><td style="text-align:right;">5.89 s</td><td style="text-align:right;"><strong>4.23 s</strong></td></tr><tr><td>CPU/GiB</td><td style="text-align:right;"><strong>0.376</strong></td><td style="text-align:right;">—</td><td style="text-align:right;">1.47</td></tr><tr><td>峰值线程</td><td style="text-align:right;">21</td><td style="text-align:right;">—</td><td style="text-align:right;">99</td></tr></tbody></table><p><strong>已追平 Explorer</strong>，且 CPU/GiB 是三者最低。剩下唯一的差距是 Pulse， 代价是它的 1.47 CPU/GiB 与 99 个线程。</p><h3 id="_4-文件查找速度-10-万文件树中按文件名找-1-个文件" tabindex="-1">4. 文件查找速度（10 万文件树中按文件名找 1 个文件） <a class="header-anchor" href="#_4-文件查找速度-10-万文件树中按文件名找-1-个文件" aria-label="Permalink to “4. 文件查找速度（10 万文件树中按文件名找 1 个文件）”">​</a></h3><table tabindex="0"><thead><tr><th>指标</th><th style="text-align:right;">ZenFile</th><th style="text-align:right;">Explorer</th><th style="text-align:right;">Pulse</th></tr></thead><tbody><tr><td>冷搜（秒）</td><td style="text-align:right;">0.856</td><td style="text-align:right;">1.167</td><td style="text-align:right;"><strong>0.704</strong></td></tr><tr><td>热搜（秒）</td><td style="text-align:right;">0.726</td><td style="text-align:right;"><strong>0.701</strong></td><td style="text-align:right;">0.706</td></tr><tr><td>搜索时 RSS（MB）</td><td style="text-align:right;">104.1</td><td style="text-align:right;"><strong>69.7</strong></td><td style="text-align:right;">279.9</td></tr></tbody></table><p>三者在同一量级（0.7～1.2 秒），<strong>差异不大</strong>。Pulse 靠常驻索引服务拿到冷搜第一， 代价是 279.9 MB 的进程内存 + 后台 79～821 MB 的索引服务。ZenFile 不建常驻索引，冷搜仍快于 Explorer。</p><h3 id="_5-大量文件加载速度-单目录-10-万文件-冷打开" tabindex="-1">5. 大量文件加载速度（单目录 10 万文件，冷打开） <a class="header-anchor" href="#_5-大量文件加载速度-单目录-10-万文件-冷打开" aria-label="Permalink to “5. 大量文件加载速度（单目录 10 万文件，冷打开）”">​</a></h3><table tabindex="0"><thead><tr><th>指标</th><th style="text-align:right;">ZenFile</th><th style="text-align:right;">Explorer</th><th style="text-align:right;">Pulse</th></tr></thead><tbody><tr><td>窗口出现（秒）</td><td style="text-align:right;"><strong>0.027</strong></td><td style="text-align:right;">0.177</td><td style="text-align:right;">0.177</td></tr><tr><td>首帧内容（秒）</td><td style="text-align:right;"><strong>0.024</strong></td><td style="text-align:right;">0.084</td><td style="text-align:right;">0.118</td></tr><tr><td>画面收敛（秒）</td><td style="text-align:right;">0.454</td><td style="text-align:right;"><strong>0.443</strong></td><td style="text-align:right;">0.791</td></tr><tr><td>总耗时（秒）</td><td style="text-align:right;"><strong>0.481</strong></td><td style="text-align:right;">0.620</td><td style="text-align:right;">0.967</td></tr><tr><td>加载后 RSS（MB）</td><td style="text-align:right;"><strong>57.6</strong></td><td style="text-align:right;">91.5</td><td style="text-align:right;">173.2</td></tr></tbody></table><p>窗口出现与首帧内容几乎在按下回车的同时完成，比另两者快 3～6 倍。</p><h3 id="_6-文件夹占用大小的计算速度-2-万文件-78-1-mb" tabindex="-1">6. 文件夹占用大小的计算速度（2 万文件 / 78.1 MB） <a class="header-anchor" href="#_6-文件夹占用大小的计算速度-2-万文件-78-1-mb" aria-label="Permalink to “6. 文件夹占用大小的计算速度（2 万文件 / 78.1 MB）”">​</a></h3><table tabindex="0"><thead><tr><th>指标</th><th style="text-align:right;">ZenFile</th><th style="text-align:right;">Explorer</th><th style="text-align:right;">Pulse</th></tr></thead><tbody><tr><td><strong>大小算完（秒）</strong></td><td style="text-align:right;"><strong>0.565</strong></td><td style="text-align:right;">0.685 ⚠</td><td style="text-align:right;">0.666</td></tr><tr><td>扫描期峰值 RSS（MB）</td><td style="text-align:right;"><strong>31.1</strong></td><td style="text-align:right;">63.1 ⚠</td><td style="text-align:right;">258～280</td></tr></tbody></table><p>⚠ Explorer 只有 1 个有效样本，仅供参考。</p><p>加了一个下界锚点：Python <code>os.walk</code> 遍历同一目录需 0.82～0.87 s， <strong>三家的计算时间都比 Python 裸遍历还快</strong>，说明这项比的就是递归遍历本身的执行效率。 ZenFile 的 0.565 s 最接近「纯遍历成本」，峰值内存只有 Pulse 的 <strong>1/8</strong>。</p><h3 id="_6-5-目录复制前的规划扫描-10-万条目" tabindex="-1">6.5 目录复制前的规划扫描（10 万条目） <a class="header-anchor" href="#_6-5-目录复制前的规划扫描-10-万条目" aria-label="Permalink to “6.5 目录复制前的规划扫描（10 万条目）”">​</a></h3><p>这一项<strong>没有三方对照</strong>，只有 ZenFile 自己的前后对比。</p><table tabindex="0"><thead><tr><th>臂</th><th style="text-align:right;">耗时</th><th style="text-align:right;">每条目</th><th style="text-align:right;">峰值工作集</th></tr></thead><tbody><tr><td><code>naive</code>（旧生产）</td><td style="text-align:right;">3.07 s</td><td style="text-align:right;">30.7 µs</td><td style="text-align:right;">44 MB</td></tr><tr><td><code>enumonly</code>（纯枚举下界）</td><td style="text-align:right;">0.033 s</td><td style="text-align:right;">0.33 µs</td><td style="text-align:right;">2 MB</td></tr><tr><td><code>prod</code>（优化前）</td><td style="text-align:right;">0.94 s</td><td style="text-align:right;">9.4 µs</td><td style="text-align:right;">43 MB</td></tr><tr><td><strong><code>prod</code>（优化后，生产代码实测）</strong></td><td style="text-align:right;"><strong>0.233 s</strong></td><td style="text-align:right;"><strong>2.3 µs</strong></td><td style="text-align:right;"><strong>43 MB</strong></td></tr></tbody></table><p><strong>净提升 13 倍</strong>，3 轮交错 A/B，取中位数。</p><div class="danger custom-block"><p class="custom-block-title">一次必须说清楚的过程失误</p><p>早期版本这里写的是「3.25 s → 0.040 s，<strong>86 倍</strong>」。那个数字<strong>是错的</strong>：</p><ol><li>基准的 engine 臂把扫描逻辑在 benchmark 里<strong>重抄了一遍</strong>，而生产 <code>collect()</code> 的文件分支当时还走 <code>src.symlink_metadata()</code>——基准测的是一条产品还没走上的路。 现在 engine 臂<strong>直接调 <code>pub fn plan_only()</code></strong>，基准和产品不可能再各自漂移。</li><li>即便在重抄的那条路上，也只对上了第一半。第二半的差距来自 <code>resolve_conflict</code> 里<strong>每个条目一次 <code>Path::exists()</code></strong>：那是一次完整的文件系统查询， 10 万条目就是 10 万次。拆成三臂后真相才暴露——<code>enumonly</code>(0.033 s) 与 <code>prod</code>(0.94 s) 之间的 0.9 s <strong>全在存在性查询上，与文件系统无关</strong>。</li></ol><p>修法是 <code>ExistCache</code>：按目录缓存一次 <code>read_dir</code> 快照，每目录只付一次枚举。</p></div><h2 id="ui-响应性" tabindex="-1">UI 响应性 <a class="header-anchor" href="#ui-响应性" aria-label="Permalink to “UI 响应性”">​</a></h2><p>「速度」不只有墙钟时间。一项操作如果在主线程上同步跑， <strong>整个窗口会僵住</strong>，用户感知到的慢比计时器上的数字难看得多。</p><p>判据用 <code>WM_NULL</code> 的<strong>往返延迟</strong>（<code>SendMessageTimeoutW</code>，5 秒超时即判卡死），不看操作结果。</p><p><strong>删除</strong>（20 000 文件 / 20 子目录）：</p><table tabindex="0"><thead><tr><th>阶段</th><th style="text-align:right;">p50</th><th style="text-align:right;">p95</th><th style="text-align:right;">worst</th><th style="text-align:right;">卡死</th></tr></thead><tbody><tr><td>空闲基线</td><td style="text-align:right;">0.1 ms</td><td style="text-align:right;">0.2 ms</td><td style="text-align:right;">0.7 ms</td><td style="text-align:right;">0</td></tr><tr><td><strong>删除中</strong></td><td style="text-align:right;"><strong>0.0 ms</strong></td><td style="text-align:right;"><strong>4.8 ms</strong></td><td style="text-align:right;"><strong>5.5 ms</strong></td><td style="text-align:right;"><strong>0</strong></td></tr><tr><td>删除后</td><td style="text-align:right;">0.1 ms</td><td style="text-align:right;">0.3 ms</td><td style="text-align:right;">0.3 ms</td><td style="text-align:right;">0</td></tr></tbody></table><p>删除本身耗时 3.3 s，期间主窗口还能切换目录（1.2 s 内列表刷新）—— 即不只是「没卡死」，而是真的在处理用户操作。</p><p><strong>批量重命名</strong>（3 000 文件）：重命名中 p50 = 0.1 ms、p95 = 0.3 ms、卡死 0。</p><h2 id="结论速览" tabindex="-1">结论速览 <a class="header-anchor" href="#结论速览" aria-label="Permalink to “结论速览”">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>第一名</th><th>ZenFile 的相对表现</th></tr></thead><tbody><tr><td>内存占用</td><td><strong>ZenFile</strong>（29.5 MB）</td><td>领先，约为 Pulse 的 1/7</td></tr><tr><td>多文件操作</td><td><strong>ZenFile</strong>（5109 文件/秒）</td><td>领先 Explorer <strong>7.6×</strong>、Pulse <strong>4.9×</strong></td></tr><tr><td><strong>单个大文件操作</strong></td><td>Pulse</td><td><strong>已追平 Explorer</strong>（5.78 vs 5.89 s）；优化前落后 2.2×，CPU/GiB −78%</td></tr><tr><td>文件查找</td><td>Pulse（冷搜）</td><td>三者同量级，ZenFile 居中间</td></tr><tr><td>大量文件加载</td><td><strong>ZenFile</strong>（0.481 s）</td><td>领先，且内存最省</td></tr><tr><td>文件夹大小计算</td><td><strong>ZenFile</strong>（0.565 s）</td><td>领先，峰值内存 1/8</td></tr><tr><td><strong>目录复制前扫描</strong></td><td><strong>ZenFile</strong></td><td><strong>13×</strong>（3.07 → 0.233 s），无三方对照</td></tr></tbody></table><p><strong>一句话</strong>：ZenFile 的优势在小文件批处理、冷启动加载、内存占用； <strong>曾经唯一的短板（单个大文件的连续写入）已经修掉</strong>； <strong>第三个短板（整棵大树复制前的规划扫描）也修掉了，13 倍</strong>。</p><h2 id="测试中发现并修复的缺陷" tabindex="-1">测试中发现并修复的缺陷 <a class="header-anchor" href="#测试中发现并修复的缺陷" aria-label="Permalink to “测试中发现并修复的缺陷”">​</a></h2><p><strong>缺陷 1：Alt 组合快捷键全部失效。</strong> <code>main.rs</code> 只处理 <code>WM_KEYDOWN</code>， 而带 Alt 的组合键走的是 <code>WM_SYSKEYDOWN</code>——所有 <code>Alt+←/→/↑/↓</code> 与 <code>Alt+Enter</code> （打开属性页）都没反应。补上 <code>WM_SYSKEYDOWN</code> 后修复。</p><p><strong>缺陷 2：<code>transfer.rs</code> 的分块粒度与注释不符。</strong> 代码里做了 <code>clamp(块数)</code>， 导致块长被压到 74 MB，与注释描述的 8 MB 不符。第一轮修复它把 CPU/GiB 降了 37%， 第二轮才找到真正的病根——<strong>用户态双拷贝路径本身</strong>。</p>`,53)])])}const y=e(l,[["render",n]]);export{x as __pageData,y as default};
